local function log_level_routes()
	local routes = {}
	for name, level in pairs(log.LEVELS) do
		routes[#routes + 1] = {
			path = { "log", name },
			desc = ("Show the internal log ring, filtered to %s and above"):format(name:upper()),
			run = function()
				log.show_ring(level)
			end,
		}
	end
	table.sort(routes, function(a, b)
		return a.path[2] < b.path[2]
	end)
	return routes
end

